/**
 * Find BOMs and mojibake in shell shims (.cmd / .bat / .ps1).
 *
 * Why this is separate from tests/encoding-check.mjs: that guard covers THIS
 * repository's sources. A launcher shim lives in the npm global directory or in a
 * version manager's folder, is generated by another tool, and breaks differently —
 * cmd.exe reads a UTF-8 BOM as ANSI, so `@ECHO off` becomes `锘緼ECHO off` and the
 * first line of every launch prints "not recognized as an internal or external
 * command" before the shim recovers and runs anyway.
 *
 * Bytes are read and reported directly, so nothing here depends on the console
 * code page.
 *
 *   node research/scan-shim-encoding.mjs [dir ...]
 */
import { readFileSync, readdirSync, statSync } from 'node:fs';
import { join, relative } from 'node:path';

const BOM_UTF8 = Buffer.from([0xef, 0xbb, 0xbf]);
const BOM_UTF16LE = Buffer.from([0xff, 0xfe]);
const BOM_UTF16BE = Buffer.from([0xfe, 0xff]);
/** Characters that only ever appear when UTF-8 Chinese was read as ANSI. */
const MOJIBAKE = /[\u9203\u9225\u9228\u9473\u9c8c\u9525\u93bf\u6d63\u7039\u5f7b\u93c1\u9370\u93a5\u92b0]/;

const DEFAULT_DIRS = [
  join(process.env.APPDATA ?? '', 'npm'),
  'D:\\DeepSeekHarness',
  'D:\\DeepSeekHarness\\_versions',
];

const roots = process.argv.slice(2).filter(arg => !arg.startsWith('-'));
const targets = roots.length > 0 ? roots : DEFAULT_DIRS;

const SHIM = /\.(cmd|bat|ps1)$/i;
const found = [];

function walk(dir, depth = 0) {
  if (depth > 4) return;
  let entries;
  try {
    entries = readdirSync(dir);
  } catch {
    return;
  }
  for (const entry of entries) {
    if (entry === 'node_modules' && depth > 0) continue;
    const full = join(dir, entry);
    let info;
    try {
      info = statSync(full);
    } catch {
      continue;
    }
    if (info.isDirectory()) {
      walk(full, depth + 1);
      continue;
    }
    if (!SHIM.test(entry)) continue;
    const bytes = readFileSync(full);
    const bom = bytes.subarray(0, 3).equals(BOM_UTF8) ? 'UTF-8 BOM'
      : bytes.subarray(0, 2).equals(BOM_UTF16LE) ? 'UTF-16LE BOM'
        : bytes.subarray(0, 2).equals(BOM_UTF16BE) ? 'UTF-16BE BOM'
          : null;
    const text = bytes.toString('utf8');
    const mojibakeLine = text.split('\n').findIndex(line => MOJIBAKE.test(line));
    if (bom !== null || mojibakeLine >= 0) {
      found.push({ path: full, size: info.size, mtime: info.mtime, bom, mojibakeLine: mojibakeLine >= 0 ? mojibakeLine + 1 : null, firstLine: text.split('\n')[0].replace(/\r$/, '') });
    }
  }
}

console.log(`scanning ${targets.length} location(s) for .cmd/.bat/.ps1 problems`);
for (const target of targets) {
  console.log(`  - ${target}`);
  walk(target);
}

if (found.length === 0) {
  console.log('\nSHIM SCAN PASS — no BOM and no mojibake in any shim found.');
  process.exit(0);
}

// A BOM means opposite things per extension, and conflating them makes the tool
// cry wolf: Windows PowerShell 5.1 reads a BOM-less UTF-8 .ps1 as ANSI, so a .ps1
// BOM is CORRECT and must be left alone; cmd.exe reads a .cmd as ANSI, so a .cmd
// BOM is a bug.
const broken = found.filter(item => item.mojibakeLine !== null || !/\.ps1$/i.test(item.path));
const expected = found.filter(item => !broken.includes(item));

if (broken.length > 0) {
  console.log(`\n${broken.length} file(s) to fix (a .cmd/.bat BOM makes cmd.exe print "锘緼ECHO off"):`);
  for (const item of broken) {
    console.log(`\n  ${item.path}`);
    console.log(`    size ${item.size}B   modified ${item.mtime.toISOString()}`);
    console.log(`    ${item.bom ?? 'no BOM'}${item.mojibakeLine === null ? '' : `   mojibake on line ${item.mojibakeLine}`}`);
    console.log(`    first line: ${JSON.stringify(item.firstLine.slice(0, 40))}`);
  }
  console.log('\nFix: strip the leading BOM bytes, then relaunch. A regenerated shim');
  console.log('(npm install -g / a version manager) can bring it back, so re-run this after upgrades.');
}

if (expected.length > 0) {
  console.log(`\n${expected.length} file(s) with a BOM that should STAY (PowerShell 5.1 needs it to read UTF-8 correctly):`);
  for (const item of expected) console.log(`  ok  ${item.path}`);
}

console.log('\n' + (broken.length === 0 ? 'SHIM SCAN PASS (only expected .ps1 BOMs)' : 'SHIM SCAN FAIL'));
process.exitCode = broken.length === 0 ? 0 : 1;
